var mysql = require('mysql');
var host = "localhost";
var username = "root";
var password = "";
var options = {
    host: host, user: username, password: password,
    database: 'ettms', connectionLimit: 10000, queueLimit: 2000000, waitForConnections: true
};

class MYSQLDB {
    constructor() {
        this.pool = this.connectDbase(options);
    }
    //---------- This function connects the database -------------
    connectDbase(options) {
        var pool = mysql.createPool(options);
        pool.getConnection(function (error, connection) {
            if (error) {
                return error;
            }
            //console.log('Connected!');
        });
        return pool;
    };
    //------------------------ End connectDbase -------------------------
    //----- This function generate the conditional part of an SQL statement -----
    generateConditions(conditions, delimiter) {
        var condclause = '';
        var andclause = delimiter || 'AND';
        var i = 1;
        if (conditions==''){
            condclause += '1';
        }
        for (let condition of conditions) {
            if (i === conditions.length) {
                condclause += `${condition} = ?`;
                break;
            }
            condclause += `${condition} = ? ${andclause} `;
            i++;
        }
        //console.log(`Return: ${condclause}`);
        return condclause;
    };
    //------------------- End generateConditions() ------------------
    //--- This function generate the fields of an SQL statement -----
    generateColumns(columns, isDistinct) {
        var columnsclause = 'SELECT ';
        if (isDistinct) columnsclause += 'DISTINCT ';
        var fromclause = ' FROM ';
        var i = 1;
        for (let colunn of columns) {
            if (i === columns.length) {
                columnsclause += `${colunn}`;
                break;
            }
            columnsclause += `${colunn}, `;
            i++;
        }
        return `${columnsclause} ${fromclause}`;
    };
    //------------------- End generateConditions() -------------
    generateGeneralSelect(table, conditions, strcount) {
       // console.log("statement");
        var selectPhrase = "SELECT * FROM";
        if(strcount) selectPhrase = "SELECT COUNT(*) AS count FROM";
        var statement = "";
        if (conditions.length > 0) {
          //  console.log(conditions);
            var condclause = this.generateConditions(conditions);
            statement = `${selectPhrase} ${table} WHERE ${condclause}`;
        } else {
            statement = `${selectPhrase} ${table} WHERE 1`;
        }
        return statement;
    };
    generateGeneralDelete(table, conditions) {
        var selectPhrase = "DELETE FROM";
        var statement = "";
        if (conditions) {
            var condclause = this.generateConditions(conditions);
            statement = `${selectPhrase} ${table} WHERE ${condclause}`;
        } else {
            statement = `${selectPhrase} ${table} WHERE 1`;
        }
       // console.log(statement);
        return statement;
    };
    generateInsert(table, conditions) {
        var selectPhrase = "INSERT INTO";
        var condclause = this.generateConditions(conditions, ",");
        var statement = `${selectPhrase} ${table} SET ${condclause}`;
        return statement;
    };
    searchAllRecords(table, conditions, values, callback) {
        var selectstatement = this.generateGeneralSelect(table, conditions);
        values = values || '1';
      //  console.error(values);
        this.pool.query(selectstatement, values, function (error, results, fields) {
            callback(error, results, fields);
        });
    };
    countAllRecords(table, conditions, values, callback) {
        var strcount= true;
        var selectstatement = this.generateGeneralSelect(table, conditions, strcount);
        values = values || '1';
       // console.error(values);
       // console.error(`${selectstatement} = ${values}`);
        this.pool.query(selectstatement, values, function (error, results, fields) {
            callback(error, results, fields);
        });
    };
    generateSpecificSelect(table, fields, isDistinct, conditions) {
        var columnsPhrase = this.generateColumns(fields, isDistinct);
        var condclause = this.generateConditions(conditions);
        var statement = `${columnsPhrase} ${table} WHERE ${condclause}`;
        return statement;
    };
    searchDistinctRecords(table, fields, conditions, values, callback) {
        var selectstatement = this.generateSpecificSelect(table, fields, true, conditions);
        values = values || '1';
       // console.error(values);
       // console.error(selectstatement);
        this.pool.query(selectstatement, values, function (error, results, fields) {
            callback(error, results, fields);
        });
    };
    

    insertRecord(table, columns, values, callback) {
        // --------- First search the db table before insertion ---------
        // If a primary key is present in the table (i.e. error) DON'T do any insertion else Do
        var MySObj = this;
        var conditions = [];
        var c = 0;
        for (let column of columns) {
            conditions.push(column);
            c++;
            if (c === 2) { break; }
        }
        this.searchAllRecords(table, conditions, values, function (error, results, fields) {
            if (!error && results.length === 0) {
                var insertstatement = MySObj.generateInsert(table, columns);
                MySObj.pool.query(insertstatement, values, function (error, results, fields) {
                    callback(error, results, fields);
                });
            } else {
                callback(error, results, fields);
            }
        });
    };
    deleteRecord(table, columns, values, callback) {
        // --------- First search the db table before deletion ---------
        // If a primary key is present in the table (i.e. error) DON'T do any insertion else Do
        var MySObj = this;
        var conditions = [];
        var c = 0;
        for (let column of columns) {
            conditions.push(column);
            c++;
            if (c === 2) { break; }
        }
        this.searchAllRecords(table, conditions, values, function (error, results, fields) {
            if (!error && results.length === 1) {
                var deletestatement = MySObj.generateGeneralDelete(table, columns);
                MySObj.pool.query(deletestatement, values, function (error, results, fields) {
                    callback(error, results, fields);
                });
            } else {
                callback(error, results, fields);
            }
        });
    };
    deleteAllRecord(table, callback) {
        // --------- First search the db table before insertion ---------
        // If a primary key is present in the table (i.e. error) DON'T do any insertion else Do
        var MySObj = this;
        var deletestatement = MySObj.generateGeneralDelete(table);
        MySObj.pool.query(deletestatement, function (error, results, fields) {
            callback(error, results, fields);
        });
    };

};

module.exports = MYSQLDB;